func resource(_ id: BuiltInPromptID) throws -> BuiltInPromptResource {
    let data = try Data(contentsOf: fileURL(for: id))
    let sha256 = Self.sha256Hex(data) // raw bytes
    guard var text = String(data: data, encoding: .utf8) else { throw BuiltInPromptRegistryError.invalidUTF8(id) }
    if text.hasSuffix(LF) { text.removeLast() }
    return BuiltInPromptResource(id: id, text: text, sha256: sha256)
}

