func readArtifact(_ reference: PromptExperimentArtifactReference) throws -> Data {
    let data = try Data(contentsOf: url(for: reference))
    guard data.count == reference.byteCount, PromptExperimentDigest.sha256(data) == reference.sha256 else {
        throw StoreError.artifactMismatch
    }
    return data
}

